function lexQuiz(wid,cat){
 const lc=LEX[lexLang(wid)],c=lc.cats[cat],w=c.words[Math.floor(Math.random()*c.words.length)],others=c.words.filter(x=>x!==w).sort(()=>Math.random()-.5).slice(0,3),choices=[w,...others].sort(()=>Math.random()-.5);LX={wid,lang:lexLang(wid),cat,i:0,q:w};
 app.innerHTML=`${bar('🎮 Quiz vocabulaire')}<div class="card lexq"><div class="lexpic">${w[2]}</div><h2>Comment dit-on « ${w[1]} » en ${lc.name.toLowerCase()} ?</h2><div class="choices">${choices.map(x=>`<button class="choice" data-a="lexanswer:${encodeURIComponent(x[0])}">${x[0]}</button>`).join('')}</div></div><button class="btn ghost wide" data-a="lexcat:${wid}|${cat}">← Revenir au lexique</button>`;}
